WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT CASE WHEN pressure >= 1019 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, device_code, MIN(reading_ts) AS started_at, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, STDDEV_SAMP(status_bits) AS status_bits_stddev, MAX(reading_ts) AS last_reading_ts FROM sessionized GROUP BY pressure_tier, device_code HAVING span_minutes < 1000000 ORDER BY device_code DESC;
